mapper.select:
select t1.* from ( select bp.patient_id patientId, bp.name, bp.mobile, bpm.card_number cardNumber, bo.abbreviation, DATE_FORMAT(bpm.card_opening_date, '%Y-%m-%d %h:%i:%s') cardOpeningDate, sum(bpm.principal_amount + bpm.bonus_amount) principalAmount, bpm.bonus_amount bonusAmount from base_patient bp join base_patient_member bpm on bp.patient_id = bpm.patient_id join base_organization bo on bo.org_id = bp.org_id
bpm.type = #{form.type}
AND bpm.member_level_id = #{form.memberLevelId}
AND bp.org_id in
#{orgId}
and DATE_FORMAT(bpm.card_opening_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bpm.card_opening_date, "%Y-%m-%d") < DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
group by bpm.card_number desc ) t1
AND t1.patientId in
#{ids}

SELECT IFNULL(SUM( bpmol.totalMemberRechargeAmount ), 0) AS totalMemberRechargeAmount, IFNULL(SUM( bpmol.totalMemberExpendAmount ), 0) AS totalMemberExpendAmount, IFNULL(SUM( bpmol.totalMemberRefundAmount ), 0) AS totalMemberRefundAmount FROM ( SELECT bo.org_id, IFNULL( bpmol.totalMemberRechargeAmount, 0 ) AS totalMemberRechargeAmount, IFNULL( bpmol1.totalMemberExpendAmount, 0 ) AS totalMemberExpendAmount, IFNULL( bpmol2.totalMemberRefundAmount, 0 ) AS totalMemberRefundAmount FROM base_organization bo LEFT JOIN ( SELECT bpmol.org_id, SUM( bpmol.principal_amount + bpmol.bonus_amount ) AS totalMemberRechargeAmount FROM ( SELECT bpmol.org_id, bpmol.principal_amount, bpmol.bonus_amount FROM base_patient_member_occur_log bpmol
AND bpmol.type = 0 AND bpmol.occur_type = 1
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}
) bpmol GROUP BY bpmol.org_id ) bpmol ON bo.org_id = bpmol.org_id LEFT JOIN ( SELECT bpmol.org_id, SUM( bpmol.principal_amount + bpmol.bonus_amount ) AS totalMemberExpendAmount FROM ( SELECT bpmol.org_id, bpmol.principal_amount, bpmol.bonus_amount FROM base_patient_member_occur_log bpmol
AND bpmol.type = 0 AND bpmol.occur_type = 2
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}
) bpmol GROUP BY bpmol.org_id ) bpmol1 ON bo.org_id = bpmol1.org_id LEFT JOIN ( SELECT bpmol.org_id, SUM( bpmol.principal_amount + bpmol.bonus_amount ) AS totalMemberRefundAmount FROM ( SELECT bpmol.org_id, bpmol.principal_amount, bpmol.bonus_amount FROM base_patient_member_occur_log bpmol
AND bpmol.type = 0 AND bpmol.occur_type = 3
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}
) bpmol GROUP BY bpmol.org_id ) bpmol2 ON bo.org_id = bpmol2.org_id GROUP BY bo.org_id ) bpmol
and bpmol.org_id in
#{item}

